import random

def random_search_v2(n, iterations=20000):
    max_nt = 0
    for _ in range(iterations):
        G = [random.randint(1, 100) for _ in range(n)]
        P = [random.randint(1, 100) for _ in range(n)]
        O = [G[i] + P[i] - 1 for i in range(n)]

        g = sorted(G, reverse=True)
        p = sorted(P, reverse=True)
        o = sorted(O, reverse=True)

        nt = 0
        for i in range(n):
            sides = sorted([g[i], p[i], o[i]])
            if sides[2] >= sides[0] + sides[1]:
                nt += 1
        if nt > max_nt:
            max_nt = nt
    return max_nt

for n in range(1, 8):
    print(f"n={n}, max_nt={random_search_v2(n, 20000)}")

